fn seg_mask(d: i32) -> i32 {
    match d {
        0 => 63,
        1 => 6,
        2 => 91,
        3 => 79,
        4 => 102,
        5 => 109,
        6 => 125,
        7 => 7,
        8 => 127,
        _ => 111,
    }
}

fn seg_col(m: i32, b: i32, rgb: i32) -> i32 {
    if ((m >> b) & 1) == 1 { rgb } else { 0x181818 }
}

fn seven_seg(x: i32, y: i32, d: i32, rgb: i32) {
    let m: i32 = seg_mask(d);
    host::display::fill_rect(x + 8, y, 32, 8, seg_col(m, 0, rgb));
    host::display::fill_rect(x + 40, y + 8, 8, 32, seg_col(m, 1, rgb));
    host::display::fill_rect(x + 40, y + 48, 8, 32, seg_col(m, 2, rgb));
    host::display::fill_rect(x + 8, y + 80, 32, 8, seg_col(m, 3, rgb));
    host::display::fill_rect(x, y + 48, 8, 32, seg_col(m, 4, rgb));
    host::display::fill_rect(x, y + 8, 8, 32, seg_col(m, 5, rgb));
    host::display::fill_rect(x + 8, y + 40, 32, 8, seg_col(m, 6, rgb));
}

fn frame(t: i32) {
    let w: i32 = host::display::width();
    let h: i32 = host::display::height();
    host::display::clear(0x000000);
    let s: i32 = (t / 60) % 100;
    seven_seg(w / 2 - 60, h / 2 - 44, s / 10, 0xff2020);
    seven_seg(w / 2 + 12, h / 2 - 44, s % 10, 0xff2020);
    host::display::draw_string(w / 2 - 60, h / 2 + 56, "SECONDS", 0x606060, 1);
    host::display::present();
}
